import { readFile, writeFile } from 'node:fs/promises'

const source = new URL('../lib/client.cjs', import.meta.url)
const target = new URL('../lib/client.js', import.meta.url)
const manifest = JSON.parse(await readFile(new URL('../package.json', import.meta.url), 'utf8'))
const client = (await readFile(source, 'utf8')).replace(/^\/\/# sourceMappingURL=.*$/m, '')
const artifact = `// Generated by scripts/wrap-client.mjs. Do not edit.
window.__ModuleLoader__.load({
  id: ${JSON.stringify(manifest.name)},
  factory(require) {
    var module = { exports: {} };
    var exports = module.exports;
${client}
    return module.exports;
  },
});
`
await writeFile(target, artifact)
console.log(`Wrapped ${manifest.name} client for the DSH module loader.`)
